    "name": "Flood Early Warning and Monitoring System – Sta. Cruz Laguna",
    "description": "This project aims to implement a real-time flood monitoring and early warning system in flood-prone barangays of Sta. Cruz, Laguna. It uses water-level sensors and SMS alerts to notify residents and local authorities during heavy rainfall, reducing risks and improving disaster preparedness.",
    "location": "Barangay San Pablo Sur, Sta. Cruz, Laguna",
    "category": "Disaster Risk Reduction & Resilience",
